function Icon({ name, size = 18, className = "" }) {
  return h(
    "svg",
    {
      className: ["workagent-icon", className].filter(Boolean).join(" "),
      width: size,
      height: size,
      viewBox: "0 0 48 48",
      fill: "none",
      stroke: "currentColor",
      strokeWidth: 3,
      strokeLinecap: "round",
      strokeLinejoin: "round",
      "aria-hidden": true,
    },
    ...(iconPaths[name] || iconPaths.harness).map((d, index) =>
      h("path", { d, key: index }),
    ),
  );
}

